import fs from 'node:fs';
import path from 'node:path';

const root = process.cwd();
const inputs = [
  'frontend/assets/css/tokens.css',
  'frontend/assets/css/components.css',
  'frontend/assets/css/motion.css',
  'frontend/assets/css/global-ui.css',
];
const output = 'frontend/assets/css/detail-foundation.css';
const bundle = [
  '/* Generated by scripts/build-detail-foundation.mjs. Do not edit by hand. */',
  ...inputs.map((file) => `/* ===== ${path.basename(file)} ===== */\n${fs.readFileSync(path.join(root, file), 'utf8').trim()}`),
  '',
].join('\n\n');
if (process.argv.includes('--check')) {
  if (!fs.existsSync(path.join(root, output)) || fs.readFileSync(path.join(root, output), 'utf8') !== bundle) {
    console.error(`FAIL: ${output} is stale; run node scripts/build-detail-foundation.mjs`);
    process.exit(1);
  }
  console.log(`PASS: ${output} matches ${inputs.length} source stylesheets`);
} else {
  fs.writeFileSync(path.join(root, output), bundle);
  console.log(`Built ${output} from ${inputs.length} source stylesheets`);
}
